class Solution:
    def countDistinct(self, nums, k, p):
        n = len(nums)
        seen = set()
        for i in range(n):
            c = 0
            for j in range(i, n):
                if nums[j] % p == 0:
                    c += 1
                if c > k:
                    break
                seen.add(tuple(nums[i:j + 1]))
        return len(seen)

