class Solution {
public:
    int countDistinct(vector<int>& nums, int k, int p) {
        int n = nums.size();
        set<vector<int>> seen;
        for (int i = 0; i < n; i++) {
            int c = 0;
            vector<int> cur;
            for (int j = i; j < n; j++) {
                if (nums[j] % p == 0) c++;
                if (c > k) break;
                cur.push_back(nums[j]);
                seen.insert(cur);
            }
        }
        return seen.size();
    }
};

