class Solution {
    public int countDistinct(int[] nums, int k, int p) {
        int n = nums.length;
        Set<List<Integer>> seen = new HashSet<>();
        for (int i = 0; i < n; i++) {
            int c = 0;
            List<Integer> cur = new ArrayList<>();
            for (int j = i; j < n; j++) {
                if (nums[j] % p == 0) c++;
                if (c > k) break;
                cur.add(nums[j]);
                seen.add(new ArrayList<>(cur));
            }
        }
        return seen.size();
    }
}

