class Solution {
public:
    int countDistinct(vector<int>& nums, int k, int p) {
        struct Node { unordered_map<int, void*> ch; };
        Node* root = new Node();
        int ans = 0, n = nums.size();
        for (int i = 0; i < n; i++) {
            int c = 0;
            Node* node = root;
            for (int j = i; j < n; j++) {
                if (nums[j] % p == 0) c++;
                if (c > k) break;
                if (!node->ch.count(nums[j])) {
                    node->ch[nums[j]] = new Node();
                    ans++;
                }
                node = (Node*)node->ch[nums[j]];
            }
        }
        return ans;
    }
};

